        <dt>Overdue claims</dt>
        <dd data-testid="dash-overdue-count">{{ counts()?.overdue ?? '' }}</dd>
      </dl>
    </section>
  `,
})
export class Dashboard {
  readonly counts = input.required<DashboardCounts | null>();
}
